/*
 * font.h -- ASCII character to font-glyph-index mapping.
 *
 * Hardware-independent (no <nes.h>, no PPU access) so it's unit-testable
 * under cc65's sim6502 target, like movement.c/room.c. The actual glyph
 * bitmaps live in font.s (CHR-ROM data, generated by tools/gen_font.py)
 * and are addressed by main.c as FONT_TILE_BASE + font_glyph_index(c).
 */

#ifndef FONT_H
#define FONT_H

/* Number of glyphs in the font set (see tools/gen_font.py's `order`). */
#define FONT_GLYPH_COUNT 43

/* Index of the blank/space glyph -- also reused as a plain filler tile
 * (e.g. a text box's background), since it's a solid, single-color tile
 * by construction. */
#define FONT_GLYPH_SPACE 0

/* Returns c's glyph index (0..FONT_GLYPH_COUNT-1) within the font tile
 * set. Lowercase letters fold to their uppercase glyph (the font only
 * has one case). Anything else unrecognized returns the space glyph. */
unsigned char font_glyph_index(char c);

#endif
